"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/components/auth/auth-context";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Pill,
  Clock,
  Calendar,
  Plus,
  Check,
  X,
  AlertCircle,
  Loader2,
  Trash2,
  RefreshCw,
  Bell,
  Pencil,
} from "lucide-react";
import { toast } from "sonner";
import {
  addMedicine,
  getMedicines,
  getReminders,
  markDoseTaken,
  deleteMedicine,
  updateMedicine,
} from "@/lib/api/userMedicines";
import type { UserMedicine, Reminder, DoseStatus } from "@/lib/types";

export default function MedicineAdherencePage() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();
  const [medicines, setMedicines] = useState<UserMedicine[]>([]);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [editingMedicine, setEditingMedicine] = useState<UserMedicine | null>(null);
  const [newMedicine, setNewMedicine] = useState({
    name: "",
    doctorName: "",
    duration: 30,
    isLifetime: false,
    intakeTimes: ["08:00"],
    notes: "",
  });

  useEffect(() => {
    if (!authLoading && !user) {
      router.push("/auth/login");
    }
  }, [user, authLoading, router]);

  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [medicinesData, remindersData] = await Promise.all([
        getMedicines(true),
        getReminders(),
      ]);
      setMedicines(medicinesData);
      setReminders(remindersData);
    } catch (error: any) {
      toast.error(error.message || "Failed to fetch data");
    } finally {
      setLoading(false);
    }
  };

  const handleAddMedicine = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMedicine.name.trim()) {
      toast.error("Medicine name is required");
      return;
    }
    if (newMedicine.intakeTimes.length === 0) {
      toast.error("At least one intake time is required");
      return;
    }

    try {
      setSaving(true);
      await addMedicine(newMedicine);
      toast.success("Medicine added successfully");
      setIsAddDialogOpen(false);
      setNewMedicine({
        name: "",
        doctorName: "",
        duration: 30,
        isLifetime: false,
        intakeTimes: ["08:00"],
        notes: "",
      });
      await fetchData();
    } catch (error: any) {
      toast.error(error.message || "Failed to add medicine");
    } finally {
      setSaving(false);
    }
  };

  const handleMarkTaken = async (doseId: string) => {
    try {
      await markDoseTaken(doseId);
      toast.success("Dose marked as taken");
      await fetchData();
    } catch (error: any) {
      toast.error(error.message || "Failed to mark dose as taken");
    }
  };

  const handleDeleteMedicine = async (id: string) => {
    try {
      await deleteMedicine(id);
      toast.success("Medicine deleted successfully");
      await fetchData();
    } catch (error: any) {
      toast.error(error.message || "Failed to delete medicine");
    }
  };

  const handleEditMedicine = (medicine: UserMedicine) => {
    setEditingMedicine(medicine);
    setIsEditDialogOpen(true);
  };

  const handleUpdateMedicine = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMedicine) return;
    
    try {
      setSaving(true);
      await updateMedicine(editingMedicine.id, {
        name: editingMedicine.name,
        doctorName: editingMedicine.doctorName || undefined,
        duration: editingMedicine.duration,
        isLifetime: editingMedicine.isLifetime,
        intakeTimes: editingMedicine.intakeTimes,
        notes: editingMedicine.notes || undefined,
      });
      toast.success("Medicine updated successfully");
      setIsEditDialogOpen(false);
      setEditingMedicine(null);
      await fetchData();
    } catch (error: any) {
      toast.error(error.message || "Failed to update medicine");
    } finally {
      setSaving(false);
    }
  };

  const addEditIntakeTime = () => {
    if (!editingMedicine) return;
    setEditingMedicine((prev) => prev ? {
      ...prev,
      intakeTimes: [...prev.intakeTimes, "20:00"],
    } : null);
  };

  const removeEditIntakeTime = (index: number) => {
    if (!editingMedicine) return;
    setEditingMedicine((prev) => prev ? {
      ...prev,
      intakeTimes: prev.intakeTimes.filter((_, i) => i !== index),
    } : null);
  };

  const updateEditIntakeTime = (index: number, value: string) => {
    if (!editingMedicine) return;
    setEditingMedicine((prev) => prev ? {
      ...prev,
      intakeTimes: prev.intakeTimes.map((t, i) => (i === index ? value : t)),
    } : null);
  };

  const addIntakeTime = () => {
    setNewMedicine((prev) => ({
      ...prev,
      intakeTimes: [...prev.intakeTimes, "20:00"],
    }));
  };

  const removeIntakeTime = (index: number) => {
    setNewMedicine((prev) => ({
      ...prev,
      intakeTimes: prev.intakeTimes.filter((_, i) => i !== index),
    }));
  };

  const updateIntakeTime = (index: number, value: string) => {
    setNewMedicine((prev) => ({
      ...prev,
      intakeTimes: prev.intakeTimes.map((t, i) => (i === index ? value : t)),
    }));
  };

  const getStatusColor = (status: DoseStatus) => {
    switch (status) {
      case "taken":
        return "bg-green-500";
      case "missed":
        return "bg-red-500";
      default:
        return "bg-yellow-500";
    }
  };

  const getStatusText = (status: DoseStatus) => {
    switch (status) {
      case "taken":
        return "Taken";
      case "missed":
        return "Missed";
      default:
        return "Pending";
    }
  };

  if (authLoading || loading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="container mx-auto max-w-6xl px-4 py-8">
      <div className="mb-8 flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Medicine Adherence</h1>
          <p className="text-muted-foreground mt-1">
            Track your medicines and stay on schedule
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={fetchData}>
            <RefreshCw className="mr-2 h-4 w-4" />
            Refresh
          </Button>
          <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
            <DialogTrigger asChild>
              <Button>
                <Plus className="mr-2 h-4 w-4" />
                Add Medicine
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Add New Medicine</DialogTitle>
                <DialogDescription>
                  Enter the details of your medicine schedule
                </DialogDescription>
              </DialogHeader>
              <form onSubmit={handleAddMedicine} className="space-y-4">
                <div>
                  <Label htmlFor="name">Medicine Name *</Label>
                  <Input
                    id="name"
                    value={newMedicine.name}
                    onChange={(e) =>
                      setNewMedicine((prev) => ({ ...prev, name: e.target.value }))
                    }
                    placeholder="e.g., Aspirin"
                    required
                  />
                </div>
                <div>
                  <Label htmlFor="doctorName">Doctor Name</Label>
                  <Input
                    id="doctorName"
                    value={newMedicine.doctorName}
                    onChange={(e) =>
                      setNewMedicine((prev) => ({
                        ...prev,
                        doctorName: e.target.value,
                      }))
                    }
                    placeholder="e.g., Dr. Smith"
                  />
                </div>
                <div className="flex items-center space-x-2">
                  <Checkbox
                    id="isLifetime"
                    checked={newMedicine.isLifetime}
                    onCheckedChange={(checked) =>
                      setNewMedicine((prev) => ({
                        ...prev,
                        isLifetime: checked as boolean,
                      }))
                    }
                  />
                  <Label htmlFor="isLifetime">Lifetime (ongoing)</Label>
                </div>
                {!newMedicine.isLifetime && (
                  <div>
                    <Label htmlFor="duration">Duration (days)</Label>
                    <Input
                      id="duration"
                      type="number"
                      min="1"
                      value={newMedicine.duration}
                      onChange={(e) =>
                        setNewMedicine((prev) => ({
                          ...prev,
                          duration: parseInt(e.target.value) || 1,
                        }))
                      }
                    />
                  </div>
                )}
                <div>
                  <Label>Intake Times *</Label>
                  <div className="space-y-2 mt-2">
                    {newMedicine.intakeTimes.map((time, index) => (
                      <div key={index} className="flex gap-2">
                        <Input
                          type="time"
                          value={time}
                          onChange={(e) => updateIntakeTime(index, e.target.value)}
                        />
                        {newMedicine.intakeTimes.length > 1 && (
                          <Button
                            type="button"
                            variant="outline"
                            size="icon"
                            onClick={() => removeIntakeTime(index)}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        )}
                      </div>
                    ))}
                    <Button
                      type="button"
                      variant="outline"
                      onClick={addIntakeTime}
                      className="w-full"
                    >
                      <Plus className="mr-2 h-4 w-4" />
                      Add Time
                    </Button>
                  </div>
                </div>
                <div>
                  <Label htmlFor="notes">Notes</Label>
                  <Input
                    id="notes"
                    value={newMedicine.notes}
                    onChange={(e) =>
                      setNewMedicine((prev) => ({ ...prev, notes: e.target.value }))
                    }
                    placeholder="Additional instructions"
                  />
                </div>
                <Button type="submit" className="w-full" disabled={saving}>
                  {saving ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    "Add Medicine"
                  )}
                </Button>
              </form>
            </DialogContent>
          </Dialog>

          {/* Edit Medicine Dialog */}
          <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Edit Medicine</DialogTitle>
                <DialogDescription>
                  Update your medicine details
                </DialogDescription>
              </DialogHeader>
              {editingMedicine && (
                <form onSubmit={handleUpdateMedicine} className="space-y-4">
                  <div>
                    <Label htmlFor="edit-name">Medicine Name *</Label>
                    <Input
                      id="edit-name"
                      value={editingMedicine.name}
                      onChange={(e) =>
                        setEditingMedicine((prev) => prev ? { ...prev, name: e.target.value } : null)
                      }
                      required
                    />
                  </div>
                  <div>
                    <Label htmlFor="edit-doctorName">Doctor Name</Label>
                    <Input
                      id="edit-doctorName"
                      value={editingMedicine.doctorName || ""}
                      onChange={(e) =>
                        setEditingMedicine((prev) => prev ? { ...prev, doctorName: e.target.value || null } : null)
                      }
                    />
                  </div>
                  <div className="flex items-center space-x-2">
                    <Checkbox
                      id="edit-isLifetime"
                      checked={editingMedicine.isLifetime}
                      onCheckedChange={(checked) =>
                        setEditingMedicine((prev) => prev ? { ...prev, isLifetime: checked as boolean } : null)
                      }
                    />
                    <Label htmlFor="edit-isLifetime">Lifetime (ongoing)</Label>
                  </div>
                  {!editingMedicine.isLifetime && (
                    <div>
                      <Label htmlFor="edit-duration">Duration (days)</Label>
                      <Input
                        id="edit-duration"
                        type="number"
                        min="1"
                        value={editingMedicine.duration}
                        onChange={(e) =>
                          setEditingMedicine((prev) => prev ? { ...prev, duration: parseInt(e.target.value) || 1 } : null)
                        }
                      />
                    </div>
                  )}
                  <div>
                    <Label>Intake Times *</Label>
                    <div className="space-y-2 mt-2">
                      {editingMedicine.intakeTimes.map((time, index) => (
                        <div key={index} className="flex gap-2">
                          <Input
                            type="time"
                            value={time}
                            onChange={(e) => updateEditIntakeTime(index, e.target.value)}
                          />
                          {editingMedicine.intakeTimes.length > 1 && (
                            <Button
                              type="button"
                              variant="outline"
                              size="icon"
                              onClick={() => removeEditIntakeTime(index)}
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          )}
                        </div>
                      ))}
                      <Button
                        type="button"
                        variant="outline"
                        onClick={addEditIntakeTime}
                        className="w-full"
                      >
                        <Plus className="mr-2 h-4 w-4" />
                        Add Time
                      </Button>
                    </div>
                  </div>
                  <div>
                    <Label htmlFor="edit-notes">Notes</Label>
                    <Input
                      id="edit-notes"
                      value={editingMedicine.notes || ""}
                      onChange={(e) =>
                        setEditingMedicine((prev) => prev ? { ...prev, notes: e.target.value || null } : null)
                      }
                    />
                  </div>
                  <Button type="submit" className="w-full" disabled={saving}>
                    {saving ? (
                      <>
                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                        Updating...
                      </>
                    ) : (
                      "Update Medicine"
                    )}
                  </Button>
                </form>
              )}
            </DialogContent>
          </Dialog>
        </div>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Pill className="h-5 w-5" />
              My Medicines
            </CardTitle>
            <CardDescription>Your active medicine schedule</CardDescription>
          </CardHeader>
          <CardContent>
            {medicines.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                <Pill className="mx-auto h-12 w-12 opacity-50" />
                <p className="mt-2">No medicines added yet</p>
                <Button
                  variant="link"
                  onClick={() => setIsAddDialogOpen(true)}
                  className="mt-2"
                >
                  Add your first medicine
                </Button>
              </div>
            ) : (
              <div className="space-y-4">
                {medicines.map((medicine) => (
                  <div
                    key={medicine.id}
                    className="flex items-center justify-between rounded-lg border p-4"
                  >
                    <div>
                      <h3 className="font-semibold">{medicine.name}</h3>
                      {medicine.doctorName && (
                        <p className="text-sm text-muted-foreground">
                          Dr. {medicine.doctorName}
                        </p>
                      )}
                      <div className="mt-1 flex flex-wrap gap-2">
                        {medicine.intakeTimes.map((time) => (
                          <Badge key={time} variant="outline">
                            <Clock className="mr-1 h-3 w-3" />
                            {time}
                          </Badge>
                        ))}
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">
                        {medicine.isLifetime
                          ? "Ongoing"
                          : `${medicine.duration} days`}
                      </p>
                    </div>
                    <div className="flex gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleEditMedicine(medicine)}
                      >
                        <Pencil className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleDeleteMedicine(medicine.id)}
                      >
                        <Trash2 className="h-4 w-4 text-destructive" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <AlertCircle className="h-5 w-5" />
              Today&apos;s Reminders
            </CardTitle>
            <CardDescription>Your scheduled doses for today</CardDescription>
          </CardHeader>
          <CardContent>
            {reminders.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                <Calendar className="mx-auto h-12 w-12 opacity-50" />
                <p className="mt-2">No reminders for today</p>
              </div>
            ) : (
              <div className="space-y-4">
                {reminders.map((reminder) => (
                  <div
                    key={reminder.id}
                    className="flex items-center justify-between rounded-lg border p-4"
                  >
                    <div>
                      <h3 className="font-semibold">{reminder.medicineName}</h3>
                      <div className="mt-1 flex items-center gap-2 text-sm text-muted-foreground">
                        <Clock className="h-3 w-3" />
                        {reminder.scheduledTime}
                        <span className="mx-1">•</span>
                        <span>{new Date(reminder.scheduledDate).toLocaleDateString()}</span>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge className={getStatusColor(reminder.status)}>
                        {getStatusText(reminder.status)}
                      </Badge>
                      {reminder.status === "pending" && (
                        <Button
                          size="sm"
                          onClick={() => handleMarkTaken(reminder.id)}
                        >
                          <Check className="mr-1 h-4 w-4" />
                          Take
                        </Button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      <Card className="mt-6">
        <CardHeader>
          <CardTitle>How It Works</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="text-center">
              <div className="mx-auto mb-2 flex h-12 w-12 items-center justify-center rounded-full bg-primary/10">
                <Plus className="h-6 w-6 text-primary" />
              </div>
              <h3 className="font-semibold">1. Add Medicines</h3>
              <p className="text-sm text-muted-foreground">
                Add your medicines with dosage times and duration
              </p>
            </div>
            <div className="text-center">
              <div className="mx-auto mb-2 flex h-12 w-12 items-center justify-center rounded-full bg-primary/10">
                <Bell className="h-6 w-6 text-primary" />
              </div>
              <h3 className="font-semibold">2. Get Reminders</h3>
              <p className="text-sm text-muted-foreground">
                Receive reminders at your scheduled times
              </p>
            </div>
            <div className="text-center">
              <div className="mx-auto mb-2 flex h-12 w-12 items-center justify-center rounded-full bg-primary/10">
                <Check className="h-6 w-6 text-primary" />
              </div>
              <h3 className="font-semibold">3. Track Progress</h3>
              <p className="text-sm text-muted-foreground">
                Mark doses as taken and track your adherence
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
